MAPPING = {
    "Percentage CPU": "system.cpu.utilization",
    "CPUUtilization": "system.cpu.utilization",
    "instance/cpu/utilization": "system.cpu.utilization",
    "Available Memory Bytes": "system.memory.available",
}

READINGS = [
    ("azure", "Percentage CPU"),
    ("aws", "CPUUtilization"),
    ("gcp", "instance/cpu/utilization"),
    ("aws", "NetworkIn"),
    ("azure", "Available Memory Bytes"),
]

def map_metric(name):
    return MAPPING.get(name, "UNMAPPED")

mapped_count = 0
for provider, name in READINGS:
    mapped = map_metric(name)
    if mapped != "UNMAPPED":
        mapped_count += 1
    print(f"{provider}/{name} -> {mapped}")

print(f"Unified: {mapped_count}/{len(READINGS)}")
